            new Promise((resolve) => {
              const reader = new FileReader()
              reader.onload = (ev) => {
                newFiles.push({
                  name: file.name,
                  content: ev.target?.result as string,
                })
                resolve()
              }
              reader.readAsText(file)
            }),
          )
        }
      }

      Promise.all(promises).then(() => {
        if (newFiles.length > 0) {
          handleAddFiles(newFiles)
          // Select the first new file
