        <MarkdownRenderer content={part.text as string} />
      </div>
    )
  }

  if (part.type === 'thinking') {
    return (
      <div className="chat-part chat-thinking">
        <div className="chat-thinking-label">Thinking</div>
        <MarkdownRenderer content={part.text as string} />
      </div>
    )
  }

  return null
}

