import { useState, useCallback, useRef } from 'react'
import { ChevronLeft, ChevronRight, Upload, FileJson, Trash2 } from 'lucide-react'

interface LogFile {
  name: string
  content: string
}

interface LogListPanelProps {
  files: LogFile[]
  selectedFile: string | null
  onSelectFile: (file: LogFile) => void
  onAddFiles: (files: LogFile[]) => void
  onRemoveFile: (name: string) => void
  isCollapsed: boolean
  onToggleCollapse: () => void
}

export function LogListPanel({
  files,
  selectedFile,
  onSelectFile,
  onAddFiles,
  onRemoveFile,
  isCollapsed,
  onToggleCollapse,
}: LogListPanelProps) {
  const [isDragOver, setIsDragOver] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFiles = useCallback(
    (fileList: FileList) => {
      const newFiles: LogFile[] = []
      const promises: Promise<void>[] = []

      for (let i = 0; i < fileList.length; i++) {
        const file = fileList[i]
        if (file && file.name.endsWith('.jsonl')) {
          promises.push(
            new Promise((resolve) => {
              const reader = new FileReader()
              reader.onload = (e) => {
                newFiles.push({
                  name: file.name,
                  content: e.target?.result as string,
                })
                resolve()
              }
              reader.readAsText(file)
            }),
          )
        }
      }

      Promise.all(promises).then(() => {
        if (newFiles.length > 0) {
          onAddFiles(newFiles)
        }
      })
    },
    [onAddFiles],
  )

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setIsDragOver(false)
      handleFiles(e.dataTransfer.files)
    },
    [handleFiles],
  )

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }, [])

  const handleDragLeave = useCallback(() => {
    setIsDragOver(false)
  }, [])

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files) {
        handleFiles(e.target.files)
      }
    },
    [handleFiles],
  )

  if (isCollapsed) {
    return (
      <aside className="sidebar sidebar-collapsed">
        <button className="sidebar-toggle" onClick={onToggleCollapse} title="Expand sidebar">
          <ChevronRight size={16} />
        </button>
        <div className="sidebar-collapsed-content">
          <span className="sidebar-collapsed-count">{files.length}</span>
          <span className="sidebar-collapsed-label">logs</span>
        </div>
        <style>{sidebarStyles}</style>
      </aside>
    )
  }

  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <h2>Log Files</h2>
        <button className="sidebar-toggle" onClick={onToggleCollapse} title="Collapse sidebar">
          <ChevronLeft size={16} />
        </button>
      </div>

      <div
        className={`drop-zone-mini ${isDragOver ? 'drag-over' : ''}`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => fileInputRef.current?.click()}
      >
        <Upload size={16} />
        <span>Drop files or click to add</span>
      </div>

      <input
        ref={fileInputRef}
        type="file"
        accept=".jsonl"
        multiple
        onChange={handleInputChange}
        style={{ display: 'none' }}
      />

      <div className="file-list">
        {files.length === 0 ? (
          <div className="file-list-empty">
            <FileJson size={32} />
            <p>No log files loaded</p>
          </div>
        ) : (
          files.map((file) => (
            <div
              key={file.name}
              className={`file-item ${selectedFile === file.name ? 'selected' : ''}`}
              onClick={() => onSelectFile(file)}
            >
              <FileJson size={14} />
              <span className="file-name" title={file.name}>
                {formatFileName(file.name)}
              </span>
              <button
                className="file-remove"
                onClick={(e) => {
                  e.stopPropagation()
                  onRemoveFile(file.name)
                }}
                title="Remove file"
              >
                <Trash2 size={12} />
              </button>
            </div>
          ))
        )}
      </div>
      <style>{sidebarStyles}</style>
    </aside>
  )
}

function formatFileName(name: string): string {
  // Format: ses_xxx_conversationID.jsonl -> conversationID
  const match = name.match(/_([a-f0-9]{8})\.jsonl$/)
  if (match?.[1]) {
    return match[1]
  }
  return name.replace('.jsonl', '')
}

